// Generate an AES-256 key from Qrypt quantum entropy and verify it with an AES-256-GCM round trip.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

try {
  process.loadEnvFile(".env");
} catch {
  // Fall back to variables already set in the environment.
}

const token = process.env.QRYPT_API_KEY;
if (!token) {
  console.error("QRYPT_API_KEY is not set.");
  process.exit(1);
}
const base = process.env.QRYPT_BASE_URL ?? "https://api-eus.qrypt.com";

const ERRORS = {
  400: "size must be between 1 and 512 KiB.",
  401: "Authorization header missing, malformed, or expired.",
  403: "Token invalid or monthly quota exhausted. Check the token first.",
  429: "Rate limited. Wait at least 10 seconds before retrying.",
};

async function fetchEntropy(sizeKiB = 1) {
  const res = await fetch(`${base}/api/v1/quantum-entropy?size=${sizeKiB}`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: "application/json",
      "User-Agent": "qrypt-aes256-quickstart/1.0",
      "X-Qrypt-Client": "quickstart",
    },
  });
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${ERRORS[res.status] ?? "Service busy or erroring; try again later."}`);
  }
  const body = await res.json();
  return Buffer.concat(body.random.map((chunk) => Buffer.from(chunk, "base64")));
}

const entropy = await fetchEntropy(1);
const key = entropy.subarray(0, 32); // 256 bits
if (key.length !== 32) throw new Error(`Expected 32 bytes of entropy, got ${key.length}`);

// Round-trip test with AES-256-GCM.
const iv = randomBytes(12);
const plaintext = "Hello from Qrypt quantum entropy!";
const cipher = createCipheriv("aes-256-gcm", key, iv);
const ciphertext = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
const tag = cipher.getAuthTag();

const decipher = createDecipheriv("aes-256-gcm", key, iv);
decipher.setAuthTag(tag);
const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");

console.log(`Received ${entropy.length} bytes of quantum entropy`);
console.log(`AES-256 key: ${key.length * 8} bits (not printed)`);
console.log(`Round trip:  ${decrypted === plaintext ? "OK" : "FAILED"}`);

